      .app {{ grid-template-columns: 1fr; }}
      .sidebar {{ position: relative; height: auto; }}
    }}
  </style>
</head>
<body>
  <div class="app">
    <aside class="sidebar">
      <div class="brand">
        <h1>MC review</h1>
        <p>Empty question crops by syllabus section. Mark fixes below each card.</p>
      </div>
      {''.join(nav)}
    </aside>
    <main class="main">
      <div class="topbar">
        <div>
          <div class="meta" id="bookLabel"></div>
          <h2 id="secTitle">Pick a section</h2>
          <div class="meta" id="secCount"></div>
        </div>
      </div>
      <div class="help">Each card is the paper crop (stem + options, no answers). Uncertain rows are highlighted. Use the form to queue a section move.</div>
      <div class="grid" id="grid"></div>
    </main>
  </div>
  <script>
    const DATA = {data_js};
    const SEC_NAMES = {json.dumps(sec_names)};
    const SECTION_OPTS = DATA.sections.map(s =>
      '<option value="' + s.num + '">' + s.num + '. ' + s.name.replace(/</g,'&lt;') + '</option>'
    ).join('');
    const grid = document.getElementById('grid');
    const bookLabel = document.getElementById('bookLabel');
    const secTitle = document.getElementById('secTitle');
    const secCount = document.getElementById('secCount');

    function esc(s) {{
      return String(s ?? '').replace(/[&<>"']/g, c => ({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));
    }}

    function badges(it) {{
      const all = String(it.sections).split(';').map(Number).filter(Boolean);
      const primary = Number(it.primary);
      let html = '<span class="badge primary">primary S' + primary + ' · ' + esc(SEC_NAMES[String(primary)] || '') + '</span>';
      for (const n of all.filter(x => x !== primary)) {{
        html += '<span class="badge secondary">also S' + n + '</span>';
      }}
      if (String(it.uncertain).toLowerCase() === 'yes') {{
        html += '<span class="badge warn">uncertain</span>';
      }}
      return html;
    }}

    function renderSection(num) {{
      const sec = DATA.sections.find(s => s.num === Number(num));
      if (!sec) return;
      document.querySelectorAll('.nav-sec').forEach(btn => {{
        btn.classList.toggle('active', Number(btn.dataset.sec) === sec.num);
      }});
      bookLabel.textContent = sec.book;
      secTitle.innerHTML = '<span class="mono">S' + sec.num + '</span> · ' + esc(sec.name);
      secCount.textContent = sec.count + ' questions';
      if (!sec.items.length) {{
        grid.innerHTML = '<p class="empty">No MC in this section yet.</p>';
        return;
      }}
      grid.innerHTML = sec.items.map(it => {{
        const qid = it.year + '-q' + it.q;
        const uncertain = String(it.uncertain).toLowerCase() === 'yes';
        const shot = it.img
          ? '<div class="shot"><img src="' + esc(it.img) + '" alt="crop" loading="lazy" /></div>'
          : '<div class="missing">Missing crop PNG</div>';
        return (
'<article class="card' + (uncertain ? ' uncertain' : '') + '" id="q-' + qid + '">' +
  '<div class="card-head">' +
    '<div class="qid"><p class="year">Year ' + esc(it.year) + '</p><p class="qn">Q' + it.q + '</p></div>' +
    '<div class="badges">' + badges(it) + '</div>' +
  '</div>' +
  shot +
  '<div class="body">' +
    '<p class="preview">' + esc(it.preview) + '</p>' +
    '<p class="reason"><strong>Reason:</strong> ' + (it.reason ? esc(it.reason) : '<span style="opacity:.6">None</span>') + '</p>' +
    '<form class="form" data-lavish-question="fix-' + qid + '" onsubmit="return window.__submitFix(event)">' +
      '<input type="hidden" name="year" value="' + esc(it.year) + '" />' +
      '<input type="hidden" name="question" value="' + it.q + '" />' +
      '<input type="hidden" name="current" value="' + sec.num + '" />' +
      '<label class="field"><span>Correct section</span><select name="target"><option value="">OK as classified</option>' + SECTION_OPTS + '</select></label>' +
      '<label class="field"><span>Note</span><input type="text" name="note" placeholder="crop / topic note" /></label>' +
      '<div class="actions"><button type="submit" class="btn btn-save">Queue fix</button></div>' +
    '</form>' +
  '</div>' +
'</article>'
        );
      }}).join('');
      history.replaceState(null, '', '#sec-' + sec.num);
    }}

    window.__submitFix = function(ev) {{
      ev.preventDefault();
      const form = ev.target;
      const year = form.year.value;
      const q = form.question.value;
      const current = form.current.value;
      const target = form.target.value;
      const note = (form.note.value || '').trim();
      const parts = ['MC fix: ' + year + ' Q' + q + ' (currently S' + current + ')'];
      if (target) parts.push('Move to S' + target + ' (' + (SEC_NAMES[target] || '') + ').');
      if (note) parts.push('Note: ' + note);
      if (!target && !note) parts.push('Marked OK.');
      if (!window.lavish || typeof window.lavish.queuePrompt !== 'function') {{
        alert(parts.join(' '));
        return false;
      }}
      window.lavish.queuePrompt(parts.join(' '), {{ tag: 'mc-fix', data: {{ year, q, current, target, note }} }});
      if (typeof window.lavish.sendQueuedPrompts === 'function') window.lavish.sendQueuedPrompts();
      form.reset();
      return false;
    }};

    document.querySelectorAll('.nav-sec').forEach(btn => {{
      btn.addEventListener('click', () => renderSection(btn.dataset.sec));
    }});
    const hash = (location.hash || '').replace('#sec-', '');
    const first = DATA.sections.find(s => s.count > 0);
    renderSection(hash || (first ? first.num : 1));
  </script>
</body>
</html>
"""
    (OUT / "index.html").write_text(html, encoding="utf-8")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Build a step-by-step pipeline Lavish review (intermediates + finals + quality)."""
from __future__ import annotations

import json
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SCRIPTS = ROOT / "scripts"
OUT = ROOT / ".lavish" / "pipeline-review"
IMG = OUT / "img"
AUDIT_JSON = ROOT / "classified" / "quality_audit.json"


def python_executable() -> str:
    venv = ROOT / ".venv" / "bin" / "python3"
    return str(venv) if venv.is_file() else sys.executable


def ensure_audit() -> dict:
    subprocess.run(
        [python_executable(), str(SCRIPTS / "quality_audit.py"), "--output", str(AUDIT_JSON)],
        check=True,
        cwd=str(ROOT),
    )
    return json.loads(AUDIT_JSON.read_text(encoding="utf-8"))


def copy_sample(src: Path, dest_name: str) -> str | None:
    if not src.is_file():
        return None
    dest = IMG / dest_name
    dest.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src, dest)
    return f"img/{dest_name}"


def collect_assets() -> dict:
    assets: dict[str, list[dict]] = {
        "anchors": [],
        "mc_crops": [],
        "lq_crops": [],
        "mc_classified": [],
        "lq_classified": [],
    }

    for page in range(1, 4):
        rel = copy_sample(
            ROOT / "output" / "2024-intermediate" / f"page{page:02d}.png",
            f"anchor-2024-page{page:02d}.png",
        )
        if rel:
            assets["anchors"].append(
                {
                    "label": f"2024 MC anchor page {page}",
                    "path": rel,
                    "note": "Blue dots must sit beside question numbers with a clear gap.",
                }
            )

    for year, question in (("2012", 1), ("2012", 15), ("2024", 1), ("2024", 4), ("2025", 1)):
        rel = copy_sample(
            ROOT / "output" / year / f"q{question}.png",
            f"mc-{year}-q{question}.png",
        )
        if rel:
            assets["mc_crops"].append(
                {
                    "label": f"MC {year} Q{question}",
                    "path": rel,
                    "note": "Empty stem + options; no answer bleed.",
                }
            )

    for year, question in (("2012", 1), ("2012", 2), ("2024", 1), ("2025", 1)):
        rel = copy_sample(
            ROOT / "output" / "lq" / year / f"q{question}.png",
            f"lq-{year}-q{question}.png",
        )
        if rel:
            assets["lq_crops"].append(
                {
                    "label": f"LQ {year} Q{question}",
                    "path": rel,
                    "note": "Full long-question crop from the paper (may span pages).",
                }
            )

    mc_samples = [
        ROOT
        / "classified"
        / "mc"
        / "01_Heat_and_Gases"
        / "02_Heat_Capacity"
        / "2012_q1.png",
        ROOT
        / "classified"
        / "mc"
        / "02_Force_and_Motion"
        / "05_Motion"
        / "2024_q4.png",
        ROOT
        / "classified"
        / "mc"
        / "03A_Wave_Motion"
        / "13_Wave_Motion"
        / "2012_q15.png",
    ]
    for src in mc_samples:
        if not src.is_file():
            # Fall back to any PNG in that section folder.
            candidates = list(src.parent.glob("*.png"))
            src = candidates[0] if candidates else src
        rel = copy_sample(src, f"classified-mc-{src.name}")
        if rel:
            assets["mc_classified"].append(
                {
                    "label": f"Bank: {src.parent.name} / {src.name}",
                    "path": rel,
                    "note": str(src.relative_to(ROOT)),
                }
            )

    lq_samples = [
        ROOT
        / "classified"
        / "lq"
        / "01_Heat_and_Gases"
        / "03_Change_of_State"
        / "2012-q1.png",
        ROOT
        / "classified"
        / "lq"
        / "02_Force_and_Motion"
        / "09_Momentum"
        / "2012-q4.png",
    ]
    for src in lq_samples:
        if not src.is_file():
            candidates = list(src.parent.glob("*-q*.png"))
            candidates = [c for c in candidates if "-ans" not in c.name]
            src = candidates[0] if candidates else src
        rel = copy_sample(src, f"classified-lq-{src.name}")
        if rel:
            assets["lq_classified"].append(
                {
                    "label": f"Bank: {src.parent.name} / {src.name}",
                    "path": rel,
                    "note": str(src.relative_to(ROOT)),
                }
            )

    return assets


def pct(rate: float) -> str:
    return f"{100 * rate:.2f}%"


def write_html(audit: dict, assets: dict) -> None:
    summary = audit["summary"]
    mc = summary["mc"]
    lq = summary["lq"]
    combined = summary["combined"]
    overrides = summary["overrides_historical"]
    passes = summary["passes_5pct_bar"]

    stages = [
        ("1. MC anchors", "mc-anchors", "Blue dots on each Paper 1A PDF → output/<year>-intermediate/anchor.pdf"),
        ("2. MC split", "mc-split", "Crop empty qN.png + combined.pdf under output/<year>/"),
        ("3. LQ pages", "lq-pages", "Export pages + starts.json under output/lq/<year>/"),
        ("4. LQ crops", "lq-crops", "Full-question crops + questions.pdf"),
        ("5. LQ answers", "lq-answers", "Marking-scheme answer crops under ans/"),
        ("6. Keys", "keys", "MC answer keys → classified/mc/answer_keys.json"),
        ("7. Classify MC", "classify-mc", "27 syllabus sections (LLM if keyed, else keywords)"),
        ("8. Classify LQ", "classify-lq", "Same sections for long questions"),
        ("9. Section PDFs", "section-pdfs", "Per-section combined.pdf / questions.pdf"),
        ("10. Performance", "performance", "LQ candidate-performance JSON"),
        ("11. Lavish", "lavish", "HTML reviews under .lavish/"),
    ]

    def gallery(items: list[dict]) -> str:
        if not items:
            return '<p class="muted">No sample assets found for this step.</p>'
        cards = []
        for item in items:
            cards.append(
                f"""
<article class="shot">
  <img src="{item['path']}" alt="{item['label']}" loading="lazy" />
  <div class="shot-cap">
    <strong>{item['label']}</strong>
    <span>{item['note']}</span>
  </div>
</article>"""
            )
        return '<div class="gallery">' + "".join(cards) + "</div>"

    stage_rows = "".join(
        f"<tr><td>{name}</td><td><code>{code}</code></td><td>{desc}</td></tr>"
        for name, code, desc in stages
    )

    fail_defs = summary["failure_definitions"]
    counted = "".join(f"<li><code>{item}</code></li>" for item in fail_defs["counted"])
    not_counted = "".join(
        f"<li><code>{item}</code></li>" for item in fail_defs["not_counted"]
    )

    override_rows = "".join(
        f"<tr><td>{year}</td><td>{count}</td></tr>"
        for year, count in sorted(overrides["by_year"].items())
    )

    status_class = "ok" if passes else "bad"
    status_text = "PASS (<=5% manual tuning)" if passes else "FAIL (above 5%)"

    html = f"""<!DOCTYPE html>
